/**
 * Prover errors.
 */
public 
enum ProverError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * File system error while opening artifacts.
     */
    case Io(message: String)
    
    /**
     * Malformed or unsupported proving artifact.
     */
    case InvalidArtifact(message: String)
    
    /**
     * Witness generation failed (bad inputs, unsatisfied assertion, graph error).
     */
    case Witness(message: String)
    
    /**
     * Malformed proof, VK or public input encoding.
     */
    case InvalidEncoding(message: String)
    
    /**
     * OS randomness unavailable.
     */
    case Rng(message: String)
    
    /**
     * The produced proof does not verify (corrupt proving key or unsatisfied constraints).
     */
    case SelfCheck(message: String)
    
    /**
     * The caller's cancellation flag was set.
     */
    case Cancelled(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ProverError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeProverError: FfiConverterRustBuffer {
    typealias SwiftType = ProverError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ProverError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Io(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .InvalidArtifact(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .Witness(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .InvalidEncoding(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Rng(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .SelfCheck(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .Cancelled(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ProverError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .Io(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .InvalidArtifact(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .Witness(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .InvalidEncoding(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Rng(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .SelfCheck(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .Cancelled(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))

        
        }
    }
}


